namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string DepartmentCode { get; set; } = "";
    public string DepartmentName { get; set; } = "";
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
}

public class Instructor
{
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

public class Department
{
    public string Code { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
    public int CourseCount { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems.", CourseCount = 4 },
            new() { Code = "MATH", Name = "Mathematics", Description = "The science of numbers, quantity, and space.", CourseCount = 3 },
            new() { Code = "ENG", Name = "English", Description = "Literature, writing, and critical analysis.", CourseCount = 3 },
            new() { Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature.", CourseCount = 2 },
            new() { Code = "HIST", Name = "History", Description = "Exploration of past events and civilizations.", CourseCount = 2 },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, methods, and object-oriented basics. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true, Instructor = new() { Name = "Dr. Alice Chen", Title = "Associate Professor", Bio = "Dr. Chen has 15 years of experience in software engineering education and has published extensively on teaching methodologies for introductory programming.", Email = "achen@university.edu" } },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design. Prerequisites: CS 101.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true, Instructor = new() { Name = "Dr. Bob Martinez", Title = "Professor", Bio = "Dr. Martinez specializes in algorithm optimization and has contributed to several open-source algorithm libraries.", Email = "bmartinez@university.edu" } },
            new() { Id = 3, Code = "CS 301", Title = "Database Systems", Description = "Relational database design, SQL, normalization, and an introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentCode = "CS", DepartmentName = "Computer Science", Instructor = new() { Name = "Dr. Alice Chen", Title = "Associate Professor", Bio = "Dr. Chen has 15 years of experience in software engineering education and has published extensively on teaching methodologies for introductory programming.", Email = "achen@university.edu" } },
            new() { Id = 4, Code = "CS 401", Title = "Software Engineering", Description = "Software development lifecycle, agile methodologies, testing, and team-based project work.", Credits = 4, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true, Instructor = new() { Name = "Prof. Diana Ross", Title = "Senior Lecturer", Bio = "Prof. Ross spent 20 years in industry at major tech companies before joining academia to mentor the next generation of engineers.", Email = "dross@university.edu" } },
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentCode = "MATH", DepartmentName = "Mathematics", IsFeatured = true, Instructor = new() { Name = "Dr. Raj Patel", Title = "Professor", Bio = "Dr. Patel is an award-winning educator known for making calculus accessible to students from all backgrounds.", Email = "rpatel@university.edu" } },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to data science.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentCode = "MATH", DepartmentName = "Mathematics", Instructor = new() { Name = "Dr. Raj Patel", Title = "Professor", Bio = "Dr. Patel is an award-winning educator known for making calculus accessible to students from all backgrounds.", Email = "rpatel@university.edu" } },
            new() { Id = 7, Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentCode = "MATH", DepartmentName = "Mathematics", Instructor = new() { Name = "Dr. Sarah Kim", Title = "Assistant Professor", Bio = "Dr. Kim's research focuses on applied statistics and machine learning, with publications in top-tier journals.", Email = "skim@university.edu" } },
            new() { Id = 8, Code = "ENG 101", Title = "English Composition", Description = "Develop critical reading and writing skills through essay writing, argumentation, and research.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentCode = "ENG", DepartmentName = "English", Instructor = new() { Name = "Prof. James Wright", Title = "Associate Professor", Bio = "Prof. Wright is a published author and has been teaching composition and rhetoric for over a decade.", Email = "jwright@university.edu" } },
            new() { Id = 9, Code = "ENG 205", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present day.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", DepartmentCode = "ENG", DepartmentName = "English", Instructor = new() { Name = "Dr. Maria Lopez", Title = "Professor", Bio = "Dr. Lopez is a renowned scholar of American literary history with multiple published books on 20th-century fiction.", Email = "mlopez@university.edu" } },
            new() { Id = 10, Code = "ENG 310", Title = "Creative Writing", Description = "Workshop-based course covering fiction, poetry, and creative non-fiction.", Credits = 3, Schedule = "Wed 6:00–8:50 PM", DepartmentCode = "ENG", DepartmentName = "English", IsFeatured = true, Instructor = new() { Name = "Prof. James Wright", Title = "Associate Professor", Bio = "Prof. Wright is a published author and has been teaching composition and rhetoric for over a decade.", Email = "jwright@university.edu" } },
            new() { Id = 11, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based. Co-requisite: MATH 101.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM + Lab Thu 2:00–4:50 PM", DepartmentCode = "PHYS", DepartmentName = "Physics", Instructor = new() { Name = "Dr. Elena Vasquez", Title = "Associate Professor", Bio = "Dr. Vasquez's research in experimental physics has earned her grants from the National Science Foundation.", Email = "evasquez@university.edu" } },
            new() { Id = 12, Code = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and introduction to modern physics.", Credits = 4, Schedule = "Mon/Wed/Fri 9:00–9:50 AM + Lab Tue 2:00–4:50 PM", DepartmentCode = "PHYS", DepartmentName = "Physics", Instructor = new() { Name = "Dr. Elena Vasquez", Title = "Associate Professor", Bio = "Dr. Vasquez's research in experimental physics has earned her grants from the National Science Foundation.", Email = "evasquez@university.edu" } },
            new() { Id = 13, Code = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from prehistory through the Renaissance.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentCode = "HIST", DepartmentName = "History", Instructor = new() { Name = "Dr. Tom Anderson", Title = "Professor", Bio = "Dr. Anderson has authored several acclaimed textbooks on world history and ancient civilizations.", Email = "tanderson@university.edu" } },
            new() { Id = 14, Code = "HIST 201", Title = "Modern World History", Description = "Major events and movements from the Enlightenment to the present day.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentCode = "HIST", DepartmentName = "History", IsFeatured = true, Instructor = new() { Name = "Dr. Tom Anderson", Title = "Professor", Bio = "Dr. Anderson has authored several acclaimed textbooks on world history and ancient civilizations.", Email = "tanderson@university.edu" } },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string code) =>
        _departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetAllCourses() => _courses;

    public List<Course> SearchCourses(string? searchTerm, string? departmentCode)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
            query = query.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.Code).ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollment(EnrollmentRequest request) => _enrollments.Add(request);
}

