arguments.file_text:
@page "/"
@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="hero-banner text-center py-5 mb-5">
    <h1 class="display-4 fw-bold">University Course Catalog</h1>
    <p class="lead text-muted">Explore departments, discover courses, and enroll today.</p>
    <a href="courses" class="btn btn-primary btn-lg mt-2">Browse All Courses</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in featuredCourses)
        {
            <div class="col">
                <CourseCatalog.Components.Shared.CourseCard Course="course" />
            </div>
        }
    </div>
</section>

<section class="mb-5">
    <h2 class="mb-3">Departments</h2>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var dept in departments)
        {
            <div class="col">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@dept.Name</h5>
                        <p class="card-text">@dept.Description</p>
                        <p class="text-muted mb-0"><small>@dept.CourseCount courses</small></p>
                    </div>
                    <div class="card-footer bg-transparent border-0 pb-3">
                        <a href="@($"courses?dept={dept.Code}")" class="btn btn-outline-secondary btn-sm">
                            View Courses
                        </a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

@code {
    private List<Models.Course> featuredCourses = new();
    private List<Models.Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
    }
}

@page "/courses"
@rendermode InteractiveServer
@using CourseCatalog.Services
@using CourseCatalog.Components.Shared
@inject CatalogService Catalog
@inject NavigationManager Nav

<PageTitle>Browse Courses</PageTitle>

<h1 class="mb-4">Browse Courses</h1>

<CourseFilters Departments="departments" OnFilterChanged="HandleFilterChanged" />

@if (filteredCourses.Count == 0)
{
    <div class="alert alert-info">
        No courses match your search. Try adjusting your filters.
    </div>
}
else
{
    <p class="text-muted mb-3">Showing @filteredCourses.Count course(s)</p>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in filteredCourses)
        {
            <div class="col">
                <CourseCard Course="course" />
            </div>
        }
    </div>
}

@code {
    private List<Models.Course> filteredCourses = new();
    private List<Models.Department> departments = new();
    private string? initialDept;

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();

        var uri = Nav.ToAbsoluteUri(Nav.Uri);
        if (Microsoft.AspNetCore.WebUtilities.QueryHelpers.ParseQuery(uri.Query)
                .TryGetValue("dept", out var dept))
        {
            initialDept = dept;
        }

        filteredCourses = Catalog.SearchCourses(null, initialDept);
    }

    private void HandleFilterChanged((string? Search, string? Department) filters)
    {
        filteredCourses = Catalog.SearchCourses(filters.Search, filters.Department);
    }
}

@page "/courses/{Id:int}"
@using CourseCatalog.Services
@using CourseCatalog.Components.Shared
@inject CatalogService Catalog

<PageTitle>@(course?.Title ?? "Course Not Found")</PageTitle>

@if (course is null)
{
    <div class="alert alert-warning">Course not found.</div>
    <a href="courses" class="btn btn-outline-secondary">Back to Courses</a>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@course.Code — @course.Title</h1>
            <div class="d-flex gap-3 mb-3">
                <span class="badge bg-primary fs-6">@course.Credits Credits</span>
                <span class="badge bg-secondary fs-6">@course.DepartmentName</span>
