+
+@code {
+    [Parameter] public List<Models.Department> Departments { get; set; } = new();
+
+    [Parameter] public EventCallback<(string? Search, string? Department)> OnFilterChanged { get; set; }
+
+    private string? _searchTerm;
+    private string? _selectedDepartment;
+
+    private string? SearchTerm
+    {
+        get => _searchTerm;
+        set { _searchTerm = value; _ = NotifyChanged(); }
+    }
+
+    private string? SelectedDepartment
+    {
+        get => _selectedDepartment;
+        set { _selectedDepartment = value; _ = NotifyChanged(); }
+    }
+
+    private Task NotifyChanged() =>
+        OnFilterChanged.InvokeAsync((_searchTerm, _selectedDepartment));
