toolArgs.file_text:
@page "/courses/{Id:int}"
@using CourseCatalog.Services
@using CourseCatalog.Components.Shared
@inject CatalogService Catalog

<PageTitle>@(course?.Title ?? "Course Not Found")</PageTitle>

@if (course is null)
{
    <div class="alert alert-warning">Course not found.</div>
    <a href="courses" class="btn btn-outline-secondary">Back to Courses</a>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@course.Code — @course.Title</h1>
            <div class="d-flex gap-3 mb-3">
                <span class="badge bg-primary fs-6">@course.Credits Credits</span>
                <span class="badge bg-secondary fs-6">@course.DepartmentName</span>
            </div>

            <h4>Description</h4>
            <p>@course.Description</p>

            <h4>Schedule</h4>
            <p><span class="bi bi-clock"></span> @course.Schedule</p>

            <a href="@($"enroll?courseId={course.Id}")" class="btn btn-success mt-2">
                Enroll in This Course
            </a>
        </div>

        <div class="col-lg-4 mt-4 mt-lg-0">
            <h4>Instructor</h4>
            <InstructorBio Instructor="course.Instructor" />
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Models.Course? course;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
    }
}

@page "/enroll"
@using CourseCatalog.Services
@using CourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
           <strong>@selectedCourseTitle</strong> has been received.</p>
        <hr />
        <p class="mb-0">You will receive a confirmation via your university email.</p>
    </div>
    <a href="courses" class="btn btn-primary">Browse More Courses</a>
}
else
{
    <div class="row">
        <div class="col-lg-6">
            <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <input type="text" class="form-control" id="studentName"
                           name="@nameof(Model.StudentName)"
                           value="@Model.StudentName"
                           required />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" class="form-control" id="studentId"
                           name="@nameof(Model.StudentId)"
                           value="@Model.StudentId"
                           placeholder="e.g. S12345678"
                           required />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select class="form-select" id="courseId"
                            name="@nameof(Model.CourseId)"
                            required>
                        <option value="">— Select a course —</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id" selected="@(course.Id == Model.CourseId)">
                                @course.Code — @course.Title (@course.Credits cr.)
                            </option>
                        }
                    </select>
                </div>

                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </form>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    private int? CourseId { get; set; }

    private List<Models.Course> courses = new();
    private bool submitted;
    private string selectedCourseTitle = "";

    protected override void OnInitialized()
    {
        courses = Catalog.GetAllCourses();
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(Model.CourseId);
        selectedCourseTitle = course is not null ? $"{course.Code} — {course.Title}" : "Unknown";
        Catalog.SubmitEnrollment(Model);
        submitted = true;
    }
}

