 @page "/enroll"
 @using CourseCatalog.Services
 @using CourseCatalog.Models
 @inject CatalogService Catalog

 <PageTitle>Enrollment Request</PageTitle>

 <h1 class="mb-4">Enrollment Request</h1>

 @if (submitted)
 {
     <div class="alert alert-success">
         <h4 class="alert-heading">Request Submitted!</h4>
         <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
            <strong>@selectedCourseTitle</strong> has been received.</p>
         <hr />
         <p class="mb-0">You will receive a confirmation via your university email.</p>
     </div>
     <a href="courses" class="btn btn-primary">Browse More Courses</a>
 }
 else
 {
     <div class="row">
         <div class="col-lg-6">
             <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
                 <AntiforgeryToken />

                 <div class="mb-3">
                     <label for="studentName" class="form-label">Full Name</label>
                     <input type="text" class="form-control" id="studentName"
                            name="@nameof(Model.StudentName)"
                            value="@Model.StudentName"
                            required />
                 </div>

                 <div class="mb-3">
                     <label for="studentId" class="form-label">Student ID</label>
                     <input type="text" class="form-control" id="studentId"
                            name="@nameof(Model.StudentId)"
                            value="@Model.StudentId"
                            placeholder="e.g. S12345678"
                            required />
                 </div>

                 <div class="mb-3">
                     <label for="courseId" class="form-label">Course</label>
                     <select class="form-select" id="courseId"
                             name="@nameof(Model.CourseId)"
                             required>
                         <option value="">— Select a course —</option>
                         @foreach (var course in courses)
                         {
                             <option value="@course.Id" selected="@(course.Id == Model.CourseId)">
                                 @course.Code — @course.Title (@course.Credits cr.)
                             </option>
                         }
                     </select>
                 </div>

                 <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                 <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
             </form>
         </div>
     </div>
 }

 @code {
     [SupplyParameterFromForm]
     private EnrollmentRequest? Model { get; set; }

     protected override void OnParametersSet()
     {
         Model ??= new();
     }

     [SupplyParameterFromQuery]
     private int? CourseId { get; set; }

     private List<Models.Course> courses = new();
     private bool submitted;
     private string selectedCourseTitle = "";

     protected override void OnInitialized()
     {
         courses = Catalog.GetAllCourses();
         if (CourseId.HasValue && Model.CourseId == 0)
         {
             Model.CourseId = CourseId.Value;
         }
     }

     private void HandleSubmit()
     {
         var course = Catalog.GetCourse(Model.CourseId);
         selectedCourseTitle = course is not null ? $"{course.Code} — {course.Title}" : "Unknown";
         Catalog.SubmitEnrollment(Model);
         submitted = true;
     }
 }

